∀ (a kappa q eta delta w1 w2 w3 : ℝ),
  have b1 := a + kappa * q * eta;
  have b2_0 := b1 ^ 2 + kappa * q * eta * (1 - eta);
  have b2_d := b1 ^ 2 + kappa * (q / 2) * ((eta - delta) * (1 - (eta - delta)) + (eta + delta) * (1 - (eta + delta)));
  b2_0 - b2_d = kappa * q * delta ^ 2 ∧
    b2_0 * w1 + b1 * w2 + w3 - (b2_d * w1 + b1 * w2 + w3) = kappa * q * delta ^ 2 * w1

∀ (b sigma_sq b1 b2 : ℝ),
  have sw_sq := b ^ 2 / 3;
  have m4_unif := b ^ 4 / 5;
  have R := (sw_sq + sigma_sq) * (sw_sq * (1 + b1 ^ 2 + b2 ^ 2) + sigma_sq) + sw_sq ^ 2 * b2 ^ 2;
  m4_unif - 3 * sw_sq ^ 2 = -2 * b ^ 4 / 15 ∧ R + b2 ^ 2 * (m4_unif - 3 * sw_sq ^ 2) ≤ R

∀ (q tau eta_bar d_eta : ℝ),
  q ≠ 0 →
    have p_minus := 1 / 2 - tau / q;
    have p_plus := 1 / 2 + tau / q;
    have w0_1 := q * p_minus;
    have w0_2 := q * p_plus;
    have eta0_1 := eta_bar - p_plus * d_eta;
    have eta0_2 := eta_bar + p_minus * d_eta;
    have w1_1 := q * p_plus;
    have w1_2 := q * p_minus;
    have eta1_1 := eta_bar - p_minus * d_eta;
    have eta1_2 := eta_bar + p_plus * d_eta;
    w1_1 * eta1_1 + w1_2 * eta1_2 - (w0_1 * eta0_1 + w0_2 * eta0_2) = 0 ∧
      w1_1 * eta1_1 ^ 2 + w1_2 * eta1_2 ^ 2 - (w0_1 * eta0_1 ^ 2 + w0_2 * eta0_2 ^ 2) = 0 ∧
        w1_1 * eta1_1 ^ 3 + w1_2 * eta1_2 ^ 3 - (w0_1 * eta0_1 ^ 3 + w0_2 * eta0_2 ^ 3) =
          4 * tau * p_minus * p_plus * d_eta ^ 3

∀ (K_t I_t p_t dp C_hedge : ℝ),
  have E_t := K_t + I_t * p_t;
  have K_next := K_t - C_hedge;
  have p_next := p_t + dp;
  have E_next := K_next + I_t * p_next;
  E_next = E_t + I_t * dp - C_hedge

have I0 := -2000;
have P0 := 100;
have E0 := 10000;
have K0 := E0 - I0 * P0;
have dp_fav := -10;
have E1_fav := K0 + I0 * (P0 + dp_fav);
have MM1_fav := 5e-3 * -I0 * (P0 + dp_fav) - 50;
have dp_adv := 10;
have E1_adv := K0 + I0 * (P0 + dp_adv);
have MM1_adv := 5e-3 * -I0 * (P0 + dp_adv) - 50;
|dp_fav| = 10 ∧
  |dp_adv| = 10 ∧
    E1_fav = 30000 ∧ MM1_fav = 850 ∧ MM1_fav < E1_fav ∧ E1_adv = -10000 ∧ MM1_adv = 1050 ∧ E1_adv < MM1_adv

∀ (eta_bar d_eta K_lecam K_upper : ℝ),
  0 < d_eta →
    0 < K_lecam →
      K_lecam ≤ K_upper →
        have q := 1 / 5;
        have p_minus := 9 / 20;
        have p_plus := 11 / 20;
        have delta_M3 :=
          q * p_plus * (eta_bar - p_minus * d_eta) ^ 3 + q * p_minus * (eta_bar + p_plus * d_eta) ^ 3 -
            (q * p_minus * (eta_bar - p_plus * d_eta) ^ 3 + q * p_plus * (eta_bar + p_minus * d_eta) ^ 3);
        have c_low := K_lecam / (99 / 10000) ^ 2;
        have c_up := K_upper / (99 / 10000) ^ 2;
        have N_lecam := K_lecam / delta_M3 ^ 2;
        have N_upper := K_upper / delta_M3 ^ 2;
        delta_M3 = 99 / 10000 * d_eta ^ 3 ∧
          N_lecam = c_low / d_eta ^ 6 ∧ N_upper = c_up / d_eta ^ 6 ∧ 0 < N_lecam ∧ N_lecam ≤ N_upper

∀ (d : ℝ),
  have abs_I := 2000;
  have mu := 5 / 1000;
  have E0 := 10000;
  have MM0 := 950;
  have R_safe := 950;
  have B_rem0 := E0 - MM0;
  have u_adm_safe := (B_rem0 - R_safe) / (abs_I * (1 + mu));
  u_adm_safe = 270 / 67 ∧
    (abs_I * (1 + mu) * d + R_safe ≤ B_rem0 ↔ d ≤ u_adm_safe) ∧
      ¬abs_I * (1 + mu) * (81 / 20) + R_safe ≤ B_rem0 ∧
        (d ≤ u_adm_safe → E0 - abs_I * d - (MM0 + mu * abs_I * d) ≥ R_safe)

∀ {State : Type u_1} (guardPolicy : State → ℝ → ℝ) (s : State) (u_bar_step u_1 u_2 : ℝ),
  have alpha_1 := guardPolicy s u_bar_step;
  have alpha_2 := guardPolicy s u_bar_step;
  (u_1 ≠ u_2 → alpha_1 = alpha_2) ∧ alpha_1 = alpha_2
